"""Session CRUD operations backed by the ``agent_sessions`` collection.

A *session* represents the work an agent performs for a single GitHub
issue. Sessions are unique per ``(repository, issue_number)`` and are
identified by a generated ``session_id``.

The functions here are intentionally synchronous (pymongo is synchronous)
and are safe to call from FastAPI background tasks.
"""

from __future__ import annotations

import logging
import uuid
from typing import Any, Dict, List, Optional

from pymongo import ReturnDocument
from pymongo.errors import DuplicateKeyError

from app.db.mongo import (
    DEFAULT_SESSION_STATUS,
    SESSION_STATUSES,
    get_agent_sessions_collection,
    utcnow,
)

logger = logging.getLogger(__name__)

#: Prefix used for generated session identifiers.
SESSION_ID_PREFIX = "sess_"


def generate_session_id() -> str:
    """Return a new unique session identifier."""

    return f"{SESSION_ID_PREFIX}{uuid.uuid4().hex}"


def _serialize(document: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Convert a MongoDB document into a plain, JSON-friendly dict."""

    if document is None:
        return None
    result = dict(document)
    if "_id" in result:
        result["_id"] = str(result["_id"])
    return result


# ---------------------------------------------------------------------------
# Create
# ---------------------------------------------------------------------------


def create_or_get_session(repository: str, issue_number: int) -> str:
    """Return the ``session_id`` for ``(repository, issue_number)``.

    Creates a new session document if none exists; otherwise returns the
    existing session's id. Safe under concurrent webhook deliveries.
    """

    collection = get_agent_sessions_collection()
    now = utcnow()

    try:
        document = collection.find_one_and_update(
            {"repository": repository, "issue_number": issue_number},
            {
                "$setOnInsert": {
                    "session_id": generate_session_id(),
                    "repository": repository,
                    "issue_number": issue_number,
                    "status": DEFAULT_SESSION_STATUS,
                    "issue_title": None,
                    "issue_body": None,
                    "comments": [],
                    "created_at": now,
                    "updated_at": now,
                }
            },
            upsert=True,
            return_document=ReturnDocument.AFTER,
        )
    except DuplicateKeyError:
        [secret redacted]
        document = collection.find_one(
            {"repository": repository, "issue_number": issue_number}
        )

    if document is None:  # pragma: no cover - defensive
        raise RuntimeError(
            f"Failed to create or retrieve session for {repository}#{issue_number}"
        )

    logger.debug(
        "Session resolved repository=%s issue=%s session_id=%s",
        repository,
        issue_number,
        document["session_id"],
    )
    return document["session_id"]


# ---------------------------------------------------------------------------
# Read
# ---------------------------------------------------------------------------


def get_session(session_id: str) -> Optional[Dict[str, Any]]:
    """Return the session document for ``session_id`` (or ``None``)."""

    return _serialize(
        get_agent_sessions_collection().find_one({"session_id": session_id})
    )


def get_session_by_issue(
    repository: str, issue_number: int
) -> Optional[Dict[str, Any]]:
    """Return the session for ``(repository, issue_number)`` (or ``None``)."""

    return _serialize(
        get_agent_sessions_collection().find_one(
            {"repository": repository, "issue_number": issue_number}
        )
    )


def query_sessions_by_status(status: str) -> List[Dict[str, Any]]:
    """Return every session with the given ``status``."""

    cursor = get_agent_sessions_collection().find({"status": status})
    return [_serialize(doc) for doc in cursor]


def query_sessions_by_repository(repository: str) -> List[Dict[str, Any]]:
    """Return every session belonging to ``repository``."""

    cursor = get_agent_sessions_collection().find({"repository": repository})
    return [_serialize(doc) for doc in cursor]


def list_sessions(
    status: Optional[str] = None,
    repository: Optional[str] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """Return sessions filtered by ``status`` and/or ``repository``."""

    query: Dict[str, Any] = {}
    if status is not None:
        query["status"] = status
    if repository is not None:
        query["repository"] = repository

    cursor = get_agent_sessions_collection().find(query)
    if limit is not None:
        cursor = cursor.limit(int(limit))
    return [_serialize(doc) for doc in cursor]


# Convenience aliases -------------------------------------------------------

def get_sessions(
    status: Optional[str] = None,
    repository: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Alias for :func:`list_sessions`."""

    return list_sessions(status=status, repository=repository)


def get_sessions_by_status(status: str) -> List[Dict[str, Any]]:
    """Alias for :func:`query_sessions_by_status`."""

    return query_sessions_by_status(status)


def get_sessions_by_repository(repository: str) -> List[Dict[str, Any]]:
    """Alias for :func:`query_sessions_by_repository`."""

    return query_sessions_by_repository(repository)


# ---------------------------------------------------------------------------
# Update
# ---------------------------------------------------------------------------


def update_session_status(session_id: str, status: str) -> None:
    """Update the ``status`` of a session."""

    if status not in SESSION_STATUSES:
        logger.warning("Setting session %s to unknown status %r", session_id, status)

    result = get_agent_sessions_collection().update_one(
        {"session_id": session_id},
        {"$set": {"status": status, "updated_at": utcnow()}},
    )
    if result.matched_count == 0:
        logger.warning("update_session_status: session %s not found", session_id)
    else:
        logger.info("Session %s status -> %s", session_id, status)


def update_issue_info(
    session_id: str, issue_title: str, issue_body: str
) -> None:
    """Store the GitHub issue title and body on the session."""

    result = get_agent_sessions_collection().update_one(
        {"session_id": session_id},
        {
            "$set": {
                "issue_title": issue_title,
                "issue_body": issue_body,
                "updated_at": utcnow(),
            }
        },
    )
    if result.matched_count == 0:
        logger.warning("update_issue_info: session %s not found", session_id)
    else:
        logger.debug("Updated issue info for session %s", session_id)


def add_comment(
    session_id: str,
    body: str,
    author: [secret redacted]
    comment_id: Optional[int] = None,
    url: Optional[str] = None,
    mentions: Optional[List[str]] = None,
    agent_mentioned: bool = False,
) -> None:
    """Append a comment to the session and record the latest comment."""

    entry: Dict[str, Any] = {
        "body": body,
        "author": [secret redacted]
        "comment_id": comment_id,
        "url": url,
        "mentions": list(mentions or []),
        "agent_mentioned": bool(agent_mentioned),
        "created_at": utcnow(),
    }
    result = get_agent_sessions_collection().update_one(
        {"session_id": session_id},
        {
            "$push": {"comments": entry},
            "$set": {"last_comment": entry, "updated_at": utcnow()},
        },
    )
    if result.matched_count == 0:
        logger.warning("add_comment: session %s not found", session_id)


def record_comment(
    repository: str,
    issue_number: int,
    body: str,
    author: [secret redacted]
    comment_id: Optional[int] = None,
    url: Optional[str] = None,
    mentions: Optional[List[str]] = None,
    agent_mentioned: bool = False,
) -> str:
    """Resolve (or create) the session and append a comment to it.

    Returns the session id.
    """

    session_id = create_or_get_session(repository, issue_number)
    add_comment(
        session_id,
        body=body,
        author=[secret redacted]
        comment_id=comment_id,
        url=url,
        mentions=mentions,
        agent_mentioned=agent_mentioned,
    )
    return session_id


# ---------------------------------------------------------------------------
# Delete
# ---------------------------------------------------------------------------


def delete_session(session_id: str) -> bool:
    """Delete a session. Returns ``True`` when a document was removed."""

    result = get_agent_sessions_collection().delete_one({"session_id": session_id})
    return result.deleted_count > 0

