"""Write and query structured agent logs in MongoDB.

Log entries are stored in the ``agent_logs`` collection (see
:mod:`app.db.mongo`), which is indexed on ``session_id`` and ``timestamp``.
"""

from __future__ import annotations

import logging
from datetime import datetime
from typing import Any, Dict, List, Mapping, Optional

from app.db.mongo import get_agent_logs_collection, utcnow
from app.logs.models import (
    DEFAULT_LOG_LEVEL,
    DEFAULT_LOG_SOURCE,
    LOG_LEVELS,
)

logger = logging.getLogger(__name__)


def _to_mapping(entry: Any) -> Dict[str, Any]:
    """Coerce ``entry`` (dict/TypedDict/model/dataclass) into a plain dict."""

    if isinstance(entry, Mapping):
        return dict(entry)
    for attr in ("model_dump", "dict"):
        method = getattr(entry, attr, None)
        if callable(method):
            return dict(method())
    if hasattr(entry, "__dict__"):
        return dict(vars(entry))
    raise TypeError(f"Cannot build a log document from {type(entry)!r}")


def _serialize(document: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Convert a MongoDB document into a plain, JSON-friendly dict."""

    if document is None:
        return None
    result = dict(document)
    if "_id" in result:
        result["_id"] = str(result["_id"])
    return result


def build_log_document(entry: Any) -> Dict[str, Any]:
    """Return a fully-populated ``agent_logs`` document from ``entry``.

    Ensures ``session_id``, ``level``, ``message``, ``source`` and
    ``timestamp`` are always present and normalises the level to lowercase.
    """

    document = _to_mapping(entry)

    level = str(document.get("level") or DEFAULT_LOG_LEVEL).lower()
    if level not in LOG_LEVELS:
        logger.warning("Unknown log level %r; storing as-is", level)

    timestamp = document.get("timestamp") or utcnow()
    if not isinstance(timestamp, datetime):
        timestamp = utcnow()

    document["session_id"] = document.get("session_id")
    document["level"] = level
    document["message"] = document.get("message") or ""
    document["source"] = document.get("source") or DEFAULT_LOG_SOURCE
    document["timestamp"] = timestamp

    metadata = document.get("metadata")
    document["metadata"] = metadata if isinstance(metadata, dict) else {}
    return document


def write_log(entry: Any) -> None:
    """Persist a structured log ``entry`` to MongoDB.

    Accepts an :class:`~app.logs.models.AgentLog`, a plain dict, or any
    object exposing ``model_dump()``/``dict()``/``__dict__``.
    """

    document = build_log_document(entry)
    result = get_agent_logs_collection().insert_one(document)
    logger.debug(
        "Wrote log level=%s session_id=%s source=%s id=%s",
        document["level"],
        document["session_id"],
        document["source"],
        result.inserted_id,
    )


def safe_write_log(entry: Any) -> Optional[str]:
    """Like :func:`write_log` but never raises.

    Returns the inserted id as a string on success, or ``None`` on failure.
    Used by request/background/CLI code paths where logging must not break
    the primary operation.
    """

    try:
        document = build_log_document(entry)
        result = get_agent_logs_collection().insert_one(document)
        return str(result.inserted_id)
    except Exception:
        logger.exception("Failed to write log entry")
        return None


def get_logs_by_session(
    session_id: str,
    level: Optional[str] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """Return log entries for ``session_id`` ordered by timestamp."""

    query: Dict[str, Any] = {"session_id": session_id}
    if level is not None:
        query["level"] = level.lower()

    cursor = get_agent_logs_collection().find(query).sort("timestamp", 1)
    if limit is not None:
        cursor = cursor.limit(int(limit))
    return [_serialize(doc) for doc in cursor]


def get_logs(
    session_id: Optional[str] = None,
    level: Optional[str] = None,
    source: Optional[str] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """Return log entries filtered by ``session_id``/``level``/``source``."""

    query: Dict[str, Any] = {}
    if session_id is not None:
        query["session_id"] = session_id
    if level is not None:
        query["level"] = level.lower()
    if source is not None:
        query["source"] = source

    cursor = get_agent_logs_collection().find(query).sort("timestamp", 1)
    if limit is not None:
        cursor = cursor.limit(int(limit))
    return [_serialize(doc) for doc in cursor]


def count_logs(session_id: Optional[str] = None) -> int:
    """Return the number of log entries (optionally for a session)."""

    query: Dict[str, Any] = {}
    if session_id is not None:
        query["session_id"] = session_id
    return get_agent_logs_collection().count_documents(query)


def delete_logs_by_session(session_id: str) -> int:
    """Delete every log entry for ``session_id``; return the count removed."""

    result = get_agent_logs_collection().delete_many({"session_id": session_id})
    return result.deleted_count


# Aliases -----------------------------------------------------------------

def get_session_logs(
    session_id: str,
    level: Optional[str] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """Alias for :func:`get_logs_by_session`."""

    return get_logs_by_session(session_id, level=level, limit=limit)


def query_logs_by_session(
    session_id: str,
    level: Optional[str] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """Alias for :func:`get_logs_by_session`."""

    return get_logs_by_session(session_id, level=level, limit=limit)

